import type { ExtensionAPI } from "@earendil-works/pi-coding-agent";
import { ConcurrentBatchRunner } from "./batch.js";
import { HerdrChildHost, SessionChildRegistry } from "./herdr/host.js";
import { loadOrCreateParentLabel, PARENT_LABEL_ENTRY } from "./parent-label.js";
import { JsonlChildResultReader } from "./results.js";
import { loadChildRolesConfig } from "./model-routing.js";
import { registerOrchestrator } from "./orchestrator.js";
import { registerSpawnPiTool } from "./tools.js";

export default function (pi: ExtensionAPI): void {
  const children = new SessionChildRegistry();
  const host = new HerdrChildHost(children);
  const childRolesConfig = loadChildRolesConfig();
  let parentLabel: string | undefined;

  pi.on("session_start", (_event, ctx) => {
    parentLabel = loadOrCreateParentLabel(ctx.sessionManager.getEntries(), (label) => {
      pi.appendEntry(PARENT_LABEL_ENTRY, { label });
    });
  });

  registerSpawnPiTool(
    pi,
    new ConcurrentBatchRunner(host, new JsonlChildResultReader()),
    () => {
      if (!parentLabel) throw new Error("Parent label is unavailable before session start");
      return parentLabel;
    },
    childRolesConfig,
  );
  registerOrchestrator(pi, childRolesConfig);

  pi.on("session_shutdown", async (event) => {
    if (event.reason === "reload") return;
    await children.closeAll(host);
  });
}

import { readFileSync } from "node:fs";
import type { ExtensionAPI, ExtensionContext } from "@earendil-works/pi-coding-agent";
import { Type, type Static } from "typebox";
import { Check } from "typebox/value";
import type { ChildRolesConfigLoadResult } from "./model-routing.js";

export const ORCHESTRATOR_STATE_ENTRY = "pi-herdr-orchestrator-state";
export const ORCHESTRATOR_INSTRUCTIONS = `Orchestrator mode is enabled. You are the Parent Pi. You own task decomposition, delegation, coordination, synthesis, and final verification.

Proactively delegate useful bounded work with spawn_pi. Use Child Pis for repository exploration, independent implementation with non-overlapping ownership, and review. Batch independent tasks concurrently. Handle trivial work and tightly coupled sequential edits directly.

Children share the current checkout. Avoid overlapping writes, inspect the resulting checkout yourself, treat child reports as inputs rather than proof, and run final verification before responding.`;

const OrchestratorStateSchema = Type.Object({ enabled: Type.Boolean() });
const SessionEntrySchema = Type.Object({
  type: Type.String(),
  customType: Type.Optional(Type.String()),
  data: Type.Optional(Type.Unknown()),
});
type SessionEntry = Static<typeof SessionEntrySchema>;
const FORK_HANDOFF_KEY = "__piHerdrOrchestratorForkState";
type OrchestratorGlobal = typeof globalThis & { [FORK_HANDOFF_KEY]?: boolean };

export function findOrchestratorState(entries: readonly SessionEntry[]): boolean | undefined {
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const entry = entries[index];
    if (
      entry.type !== "custom" ||
      entry.customType !== ORCHESTRATOR_STATE_ENTRY ||
      !Check(OrchestratorStateSchema, entry.data)
    )
      continue;
    return entry.data.enabled;
  }
}

export function readOrchestratorState(path: string): boolean | undefined {
  try {
    const entries = readFileSync(path, "utf8")
      .split("\n")
      .flatMap((line): SessionEntry[] => {
        if (!line.trim()) return [];
        try {
          const entry = JSON.parse(line);
          return Check(SessionEntrySchema, entry) ? [entry] : [];
        } catch {
          return [];
        }
      });
    return findOrchestratorState(entries);
  } catch {
    return undefined;
  }
}

export function registerOrchestrator(pi: ExtensionAPI, configResult: ChildRolesConfigLoadResult): void {
  let enabled = false;

  const available = () => configResult.ok && hasHerdrParentEnvironment() && pi.getActiveTools().includes("spawn_pi");

  function updateStatus(ctx: ExtensionContext): void {
    ctx.ui.setStatus("orchestrator", enabled && available() ? ctx.ui.theme.fg("accent", "orchestrator") : undefined);
  }

  function persist(): void {
    pi.appendEntry(ORCHESTRATOR_STATE_ENTRY, { enabled });
  }

  function setEnabled(next: boolean, ctx: ExtensionContext): void {
    if (next && !available()) {
      enabled = false;
      updateStatus(ctx);
      ctx.ui.notify(unavailableMessage(configResult), "warning");
      return;
    }
    enabled = next;
    persist();
    updateStatus(ctx);
    ctx.ui.notify(`Orchestrator mode ${enabled ? "enabled" : "disabled"}.`, "info");
  }

  pi.registerCommand("orchestrator", {
    description: "Toggle or inspect Parent orchestrator mode",
    getArgumentCompletions: (prefix) => {
      const values = ["on", "off", "status", "toggle"];
      const matches = values.filter((value) => value.startsWith(prefix)).map((value) => ({ value, label: value }));
      return matches.length ? matches : null;
    },
    handler: async (args, ctx) => {
      const action = args.trim().toLowerCase() || "toggle";
      if (action === "status") {
        ctx.ui.notify(
          available() ? `Orchestrator mode is ${enabled ? "enabled" : "disabled"}.` : unavailableMessage(configResult),
          available() ? "info" : "warning",
        );
        return;
      }
      if (action === "off") return setEnabled(false, ctx);
      if (!available()) {
        ctx.ui.notify(unavailableMessage(configResult), "warning");
        return;
      }
      if (action === "on") return setEnabled(true, ctx);
      if (action === "toggle") return setEnabled(!enabled, ctx);
      ctx.ui.notify("Usage: /orchestrator [on|off|status|toggle]", "error");
    },
  });

  pi.on("session_before_fork", () => {
    // SAFETY: This extension owns FORK_HANDOFF_KEY on globalThis and stores only the local boolean state.
    (globalThis as OrchestratorGlobal)[FORK_HANDOFF_KEY] = enabled;
  });

  pi.on("session_start", (event, ctx) => {
    // SAFETY: This extension owns FORK_HANDOFF_KEY on globalThis and reads it only as an optional boolean.
    const shared = globalThis as OrchestratorGlobal;
    const memoryHandoff = event.reason === "fork" ? shared[FORK_HANDOFF_KEY] : undefined;
    delete shared[FORK_HANDOFF_KEY];
    const entries = ctx.sessionManager.getEntries();
    const stored = findOrchestratorState(entries);
    const fileHandoff =
      event.reason === "fork" && event.previousSessionFile
        ? readOrchestratorState(event.previousSessionFile)
        : undefined;
    const inherited = memoryHandoff ?? fileHandoff;
    enabled = inherited ?? stored ?? (configResult.ok ? configResult.config.orchestrator.enabled : false);

    if (!configResult.ok) {
      enabled = false;
      if (ctx.hasUI) ctx.ui.notify(unavailableMessage(configResult), "warning");
    } else if (available() && (inherited !== undefined || stored === undefined)) {
      persist();
    }
    updateStatus(ctx);
  });

  pi.on("before_agent_start", (event, ctx) => {
    updateStatus(ctx);
    if (!enabled || !available()) return;
    return { systemPrompt: `${event.systemPrompt}\n\n${ORCHESTRATOR_INSTRUCTIONS}` };
  });
}

function hasHerdrParentEnvironment(): boolean {
  return (
    process.env.HERDR_ENV === "1" &&
    Boolean(process.env.HERDR_WORKSPACE_ID) &&
    Boolean(process.env.HERDR_TAB_ID) &&
    Boolean(process.env.HERDR_PANE_ID) &&
    Boolean(process.env.HERDR_SOCKET_PATH)
  );
}

function unavailableMessage(configResult: ChildRolesConfigLoadResult): string {
  return configResult.ok
    ? "Orchestrator mode requires a Herdr Parent with spawn_pi active."
    : `Invalid config at ${configResult.path}: ${configResult.error}. Orchestrator mode is disabled and spawn_pi is blocked.`;
}

export function roleGuidance(config: ChildRolesConfig): string | undefined {
  const roles = Object.entries(config.roles);
  if (!roles.length) return undefined;
  return `Configured Child Roles: ${roles.map(([name, role]) => (role.description ? `${name} (${role.description})` : name)).join("; ")}`;
}

function rolesDirectoryFor(configPath: string): string {
  const extension = extname(configPath);
  return join(extension ? configPath.slice(0, -extension.length) : configPath, "roles");
}

function loadRolesDirectory(path: string): Record<string, ChildRole> {
  let entries;
  try {
    entries = readdirSync(path, { withFileTypes: true });
  } catch (error) {
    if (error instanceof Error && isMissing(error)) return {};
    throw new ConfigSourceError(path, error);
  }

  const roles: [string, ChildRole][] = [];
  for (const entry of entries.sort((left, right) => (left.name < right.name ? -1 : left.name > right.name ? 1 : 0))) {
    if (!entry.isFile() || !entry.name.endsWith(".md")) continue;
    const name = entry.name.slice(0, -3);
    const documentPath = join(path, entry.name);
    try {
      if (!nonWhitespace(name)) throw new Error("role names must be non-whitespace strings");
      roles.push([name, parseRoleDocument(readFileSync(documentPath, "utf8"), documentPath)]);
    } catch (error) {
      throw new ConfigSourceError(documentPath, error);
    }
  }
  return Object.fromEntries(roles);
}

function parseRoleDocument(contents: string, path: string): RoleFrontmatter & { prompt: string } {
  let frontmatter: RoleFrontmatter = {};
  let prompt = contents;
  const openingLength = contents.startsWith("---\r\n")
    ? 5
    : contents.startsWith("---\n")
      ? 4
      : contents === "---"
        ? 3
        : 0;

  if (openingLength) {
    let lineStart = openingLength;
    let closingStart = -1;
    let bodyStart = -1;
    while (lineStart <= contents.length) {
      const newline = contents.indexOf("\n", lineStart);
      const lineEnd = newline === -1 ? contents.length : newline;
      const line = contents.slice(lineStart, lineEnd).replace(/\r$/, "");
      if (line === "---") {
        closingStart = lineStart;
        bodyStart = newline === -1 ? contents.length : newline + 1;
        break;
      }
      if (newline === -1) break;
      lineStart = newline + 1;
    }
    if (closingStart === -1) throw new Error(`Unterminated YAML frontmatter in ${path}`);
    const document = parseYamlDocument(contents.slice(openingLength, closingStart), {
      version: "1.2",
      uniqueKeys: true,
      customTags: [],
    });
    const yamlProblem = document.errors[0] ?? document.warnings[0];
    if (yamlProblem) throw yamlProblem;
    const value: unknown = document.toJS({ maxAliasCount: 100 });
    if (value !== null && value !== undefined && !Check(ObjectSchema, value))
      throw new Error("frontmatter must be an object");
    // SAFETY: YAML returned nullish empty frontmatter or TypeBox verified an object with ConfigInput-compatible fields.
    frontmatter = parseRoleFrontmatter(value as ConfigObject | null | undefined, "frontmatter");
    prompt = contents.slice(bodyStart);
  }

  return { ...frontmatter, prompt: parseNonWhitespace(prompt.trim(), "prompt") };
}

function parseRoleFrontmatter(value: ConfigObject | null | undefined, name: string): RoleFrontmatter {
  if (value === null || value === undefined) return {};
  const metadata = parseObject(value, name);
  rejectUnsupported(metadata, ["description", "model", "thinking"], name);
  const result: RoleFrontmatter = {};
  if (metadata.description !== undefined)
    result.description = parseNonWhitespace(metadata.description, `${name}.description`);
  if (metadata.model !== undefined) result.model = validateModel(metadata.model, `${name}.model`);
  if (metadata.thinking !== undefined) result.thinking = validateThinking(metadata.thinking, `${name}.thinking`);
  return result;
}

function parseConfig(value: ConfigInput, rolesPath: string): Omit<HerdrSubagentsConfig, "roles"> {
  const config = parseObject(value, "config");
  if (Object.prototype.hasOwnProperty.call(config, "roles"))
    throw new Error(`config.roles is no longer supported; move each role to ${join(rolesPath, "<name>.md")}`);
  rejectUnsupported(config, ["orchestrator", "defaults"], "config");
  const orchestrator = config.orchestrator === undefined ? { enabled: false } : parseOrchestrator(config.orchestrator);
  const defaults = config.defaults === undefined ? {} : parseDefaults(config.defaults, "defaults");
  return { orchestrator, defaults };
}

function parseOrchestrator(value: ConfigInput): OrchestratorConfig {
  const orchestrator = parseObject(value, "orchestrator");
  rejectUnsupported(orchestrator, ["enabled"], "orchestrator");
  if (!Check(Type.Boolean(), orchestrator.enabled)) throw new Error("orchestrator.enabled must be a boolean");
  return { enabled: orchestrator.enabled };
}

function parseDefaults(value: ConfigInput, name: string): ChildRuntimeDefaults {
  const defaults = parseObject(value, name);
  rejectUnsupported(defaults, ["model", "thinking"], name);
  const result: ChildRuntimeDefaults = {};
  if (defaults.model !== undefined) result.model = validateModel(defaults.model, `${name}.model`);
  if (defaults.thinking !== undefined) result.thinking = validateThinking(defaults.thinking, `${name}.thinking`);
  return result;
}

function validateModel(value: ConfigInput, name: string): ConfiguredModel {
  if (Check(ArraySchema, value)) {
    if (!value.length) throw new Error(`${name} must be a non-empty array of exact provider/model-id strings`);
    return value.map((candidate, index) => validateModelReference(candidate, `${name}[${index}]`));
  }
  return validateModelReference(value, name);
}

function validateModelReference(value: ConfigInput, name: string): string {
  if (!nonWhitespace(value) || value !== value.trim() || !parseModel(value))
    throw new Error(`${name} must be an exact provider/model-id`);
  return value;
}

function validateThinking(value: ConfigInput, name: string): ChildThinkingLevel {
  if (!Check(ThinkingLevelSchema, value)) throw new Error(`${name} must be one of ${THINKING_LEVELS.join(", ")}`);
  return value;
}

function parseModel(value: string): ModelReference | undefined {
  const slash = value.indexOf("/");
  if (slash < 1 || slash === value.length - 1) return undefined;
  const provider = value.slice(0, slash);
  const id = value.slice(slash + 1);
  return nonWhitespace(provider) && nonWhitespace(id) && provider === provider.trim() && id === id.trim()
    ? { provider, id }
    : undefined;
}

function selectAvailableModel(
  choice: Selection<ConfiguredModel>,
  availableModels: readonly ModelReference[],
): ModelReference | undefined {
  if (choice.value === undefined) return undefined;
  const candidates = Array.isArray(choice.value) ? choice.value : [choice.value];
  if (choice.source === "parent") return parseModel(candidates[0]);
  return candidates
    .map(parseModel)
    .find(
      (candidate): candidate is ModelReference =>
        candidate !== undefined &&
        availableModels.some((model) => model.provider === candidate.provider && model.id === candidate.id),
    );
}

